class Side(str, Enum):
    BUY = 'buy'
    SELL = 'sell'

    @classmethod
    def parse(cls, value: Any) -> 'Side':
        normalized = str(value or '').strip().lower()
        if normalized in {'buy', 'b'}:
            return cls.BUY
        if normalized in {'sell', 's', 'a'}:
            return cls.SELL
        raise ValueError(f'unsupported side: {value!r}')

