def normalize_language(lang: str) -> str:
    language_map = {key.lower(): key for key in SUPPORTED_LANGUAGES}
    return language_map.get((lang or '').lower(), 'en')

def _t(lang: str, key: str) -> str:
    return _I18N[normalize_language(lang)].get(key, _I18N['en'][key])

def _money(value: Any, *, signed: bool=True) -> str:
    number = float(value or 0)
    prefix = '+' if signed and number >= 0 else '-' if number < 0 else ''
    return f'{prefix}${abs(number):,.2f}'

def _percent(value: Any) -> str:
    return 'N/A' if value is None else f'{float(value):.2f}%'

def _holding_time(seconds: Any, *, lang: str) -> str:
    value = float(seconds or 0)
    if value >= 86400:
        return f"{value / 86400:.1f} {_t(lang, 'days')}"
    if value >= 3600:
        return f"{value / 3600:.1f} {_t(lang, 'hours')}"
    return f"{value / 60:.1f} {_t(lang, 'mins')}"

def _display_width(value: str) -> int:
    width = 0
    for character in value:
        codepoint = ord(character)
        if unicodedata.combining(character) or codepoint in {8205, 65039}:
            continue
        if unicodedata.east_asian_width(character) in {'W', 'F'} or 126976 <= codepoint <= 129791:
            width += 2
        else:
            width += 1
    return width

def _fit_display(value: Any, width: int, *, align: str='left', truncate: bool=False) -> str:
    text = str(value)
    if truncate and _display_width(text) > width:
        shortened = ''
        for character in text:
            if _display_width(shortened + character + '~') > width:
                break
            shortened += character
        text = shortened + '~'
    padding = max(0, width - _display_width(text))
    return ' ' * padding + text if align == 'right' else text + ' ' * padding

def _compact_money(value: Any, *, signed: bool=True, decimals: int=2) -> str:
    number = float(value or 0)
    prefix = '+' if signed and number >= 0 else '-' if number < 0 else ''
    amount = abs(number)
    if amount >= 1000000:
        return f'{prefix}${amount / 1000000:.1f}M'
    if amount >= 1000:
        return f'{prefix}${amount / 1000:.1f}K'
    return f'{prefix}${amount:,.{decimals}f}'

def _roi_text(pnl: Any, invested: Any) -> str:
    cost = float(invested or 0)
    if cost <= 0:
        return 'N/A'
    roi = float(pnl or 0) / cost * 100
    prefix = '+' if roi >= 0 else '-'
    amount = abs(roi)
    if amount >= 1000:
        return f'{prefix}{amount / 1000:.1f}K%'
    return f'{prefix}{amount:.2f}%'

def _compact_holding_time(seconds: Any, *, is_closed: bool | None) -> str:
    if is_closed is False:
        return 'Open'
    if seconds is None:
        return 'N/A'
    value = max(0, int(float(seconds)))
    if value < 60:
        return f'{value}s'
    if value < 3600:
        return f'{value // 60}m'
    if value < 86400:
        return f'{value // 3600}h{value % 3600 // 60}m'
    return f'{value // 86400}d{value % 86400 // 3600}h'

def _identity(profile: Mapping[str, Any]) -> str:
    name = str(profile.get('name') or profile.get('twitter_name') or '')
    username = str(profile.get('twitter_username') or '')
    if not name and (not username):
        return ''
    label = escape(name or username)
    if username:
        label += f' (@{escape(username)})'
    return label

@dataclass(frozen=True)
class _StoredReportContext:
    config: BacktestConfig
    data_quality: Mapping[str, Any]
    processed_trade_count: int

def _build_report(result: BacktestResult | _StoredReportContext, metrics: Mapping[str, Any], *, wallet_address: str, lang: str, profile: Mapping[str, Any], referral_url: str, recent_limit: int, daily_limit: int) -> str:
    lang = normalize_language(lang)
    wallet = escape(wallet_address or 'unknown')
    referral = escape(referral_url, quote=True)
    web_url = escape(f"{PUBLIC_WALLET_URL_PREFIX}{str(wallet_address or '').strip().lower()}", quote=True)
    identity = _identity(profile)
    target_pnl = metrics['actual_pnl']
    copy_pnl = metrics['copy_backtest_pnl']

    def metric_line(key: str, value: str) -> str:
        label = _t(lang, key)
        return f'{escape(_fit_display(label, 16))} {escape(str(value))}'
    title = f"💹 <b>{escape(_t(lang, 'title'))}:</b> <code>{wallet}</code>" + (f' (<b>{identity}</b>)' if identity else '') + f''' / <a href="{referral}">⚡️ {escape(_t(lang, 'copy_trade'))}</a>''' + f' / <a href="{web_url}">🔗 View in Web</a>'
    lines = [title, '', f"📈 <b>{escape(_t(lang, 'score'))}: {metrics['score']}/100</b>", '<pre><code>']
    lines.extend([metric_line('target_pnl', _money(target_pnl)), metric_line('copy_pnl', _money(copy_pnl)), metric_line('copy_loss', _percent(metrics['copy_loss_rate'])), metric_line('retention', _percent(metrics['pnl_retention_rate']))])
    if target_pnl <= 0:
        lines.append(metric_line('extra_loss', _money(metrics['extra_loss_usd'], signed=False)))
    lines.extend([metric_line('last_2d', f"{metrics['last_2d_profit_share']:.2f}%"), metric_line('target_wr', f"{metrics['target_token_win_rate']:.2f}%"), metric_line('token_wr', f"{metrics['token_win_rate']:.2f}%"), metric_line('sell_wr', f"{metrics['sell_win_rate']:.2f}%"), metric_line('pl_ratio', f"{metrics['avg_profit_loss_ratio']:.2f}"), metric_line('trading_days', str(metrics['trading_days'])), metric_line('required_cash', _money(metrics['required_starting_cash_usd'], signed=False)), metric_line('cash_roi', _percent(metrics['copy_roi_on_required_cash'])), '---------------------------------------', metric_line('trades', str(metrics['processed_trade_count'])), metric_line('tokens', str(metrics['tokens_traded'])), metric_line('volume', _money(metrics['trading_volume'], signed=False)), metric_line('buys_sells', f"{metrics['buy_count']}/{metrics['sell_count']}"), metric_line('open_tokens', str(metrics['open_token_count'])), metric_line('winning_roi', f"{metrics['winning_token_roi']:.2f}%"), metric_line('avg_buy', f"${metrics['avg_buy_in_price']:.6f}"), metric_line('avg_sell', f"${metrics['avg_sell_price']:.6f}"), metric_line('avg_cost', _money(metrics['avg_invest_per_token'], signed=False)), metric_line('avg_target', _money(metrics['avg_pnl_per_token'])), metric_line('avg_copy', _money(metrics['avg_copy_pnl_per_token'])), metric_line('median_hold', _holding_time(metrics['median_holding_time_seconds'], lang=lang)), metric_line('last_active', str(metrics['last_active'] or '-')), '---------------------------------------', '</code></pre>'])
    recent_stats = metrics['recent_20_stats']
    recent = list(metrics['recent_20_tokens'])[:recent_limit]
    lines.extend([f"<b>🕒 {escape(_t(lang, 'recent'))}</b>", '<pre><code>', f"{escape(_fit_display(_t(lang, 'target_pnl'), 12))} {_money(recent_stats['actual_pnl'])}", f"{escape(_fit_display(_t(lang, 'copy_pnl'), 12))} {_money(recent_stats['copy_backtest_pnl'])}", f"{escape(_fit_display(_t(lang, 'loss'), 12))} {_percent(recent_stats['copy_loss_rate'])}", f"{escape(_fit_display(_t(lang, 'win_rate'), 12))} {recent_stats['win_rate']:.1f}%"])
    if recent_stats['actual_pnl'] <= 0:
        lines.append(f"{escape(_fit_display(_t(lang, 'extra_loss'), 12))} {_money(recent_stats['extra_loss_usd'], signed=False)}")
    token_width, roi_width, hold_width = (14, 8, 8)
    lines.extend(['', 'LATEST 10', f"{_fit_display('Token / Date', token_width)} {_fit_display('PNL', roi_width, align='right')} {_fit_display('Copy', roi_width, align='right')} {_fit_display('Hold', hold_width, align='right')}", f"{'-' * token_width} {'-' * roi_width} {'-' * roi_width} {'-' * hold_width}"])
    all_tokens = list(metrics.get('all_tokens') or metrics.get('all_markets') or [])
    stored_tokens = {str(row.get('token_address') or row.get('condition_id') or '').lower(): row for row in all_tokens}
    for row in recent[:10]:
        token_address = str(row.get('token_address') or '').lower()
        stored_token = stored_tokens.get(token_address, {})
        symbol = _fit_display(str(row.get('title') or token_address), 8, truncate=True)
        time_str = str(row.get('time_str') or '')[:5].replace('.', '-')
        label = f'{symbol} {_fit_display(time_str, 5)}'
        copy_invested = row.get('copy_invested', row.get('invested'))
        target_invested = row.get('target_invested')
        if target_invested is None and copy_invested is not None:
            config = metrics.get('config') or {}
            buy_penalty = float(config.get('buy_price_penalty') or 0)
            copy_fee_rate = float(config.get('copy_fee_rate') or 0)
            fixed_cost = float(config.get('copy_fixed_cost_usd') or 0)
            inferred_cost = float(copy_invested) - fixed_cost * int(row.get('buy_count') or 0)
            divisor = (1 + buy_penalty) * (1 + copy_fee_rate)
            if inferred_cost > 0 and divisor > 0:
                target_invested = inferred_cost / divisor
        if target_invested is None:
            target_invested = stored_token.get('invested')
        is_closed = row.get('is_closed', stored_token.get('is_closed'))
        holding_time = row.get('holding_time_seconds')
        if holding_time is None and is_closed is True:
            first_buy = float(stored_token.get('first_buy_time') or 0)
            last_active = float(stored_token.get('last_active') or 0)
            if first_buy and last_active >= first_buy:
                holding_time = last_active - first_buy
        target_roi = _roi_text(row.get('actual_pnl'), target_invested)
        copy_roi = _roi_text(row.get('bt_copy_pnl'), copy_invested)
        hold = _compact_holding_time(holding_time, is_closed=is_closed)
        lines.append(f"{escape(label)} {_fit_display(target_roi, roi_width, align='right')} {_fit_display(copy_roi, roi_width, align='right')} {_fit_display(hold, hold_width, align='right')}")
    previous_copy_rois = [_roi_text(row.get('bt_copy_pnl'), row.get('copy_invested', row.get('invested'))) for row in recent[10:20]]
    if previous_copy_rois:
        lines.extend(['', f'PREVIOUS {len(previous_copy_rois)} COPY ROI'])
        for index in range(0, len(previous_copy_rois), 5):
            lines.append(' '.join((_fit_display(value, roi_width, align='right') for value in previous_copy_rois[index:index + 5])))
    lines.append('</code></pre>')
    daily = list(metrics['daily_stats'])[:daily_limit]
    date_width, trades_width, volume_width, pnl_width = (5, 4, 7, 9)
    lines.extend([f"<b>📅 {escape(_t(lang, 'daily'))}</b>", '<pre><code>', f"{_fit_display('Date', date_width)} {_fit_display('Tx', trades_width, align='right')} {_fit_display('Volume', volume_width, align='right')} {_fit_display('PNL', pnl_width, align='right')} {_fit_display('Copy', pnl_width, align='right')}", f"{'-' * date_width} {'-' * trades_width} {'-' * volume_width} {'-' * pnl_width} {'-' * pnl_width}"])
    for row in daily:
        volume = float(row['volume'])
        volume_text = _compact_money(volume, signed=False, decimals=0)
        lines.append(f"{_fit_display(row['date'][5:], date_width)} {_fit_display(int(row['trades']), trades_width, align='right')} {_fit_display(volume_text, volume_width, align='right')} {_fit_display(_compact_money(row['actual_pnl']), pnl_width, align='right')} {_fit_display(_compact_money(row['bt_copy_pnl']), pnl_width, align='right')}")
    lines.append('</code></pre>')
    if result.data_quality.get('starting_inventory_unknown'):
        lines.append(f"⚠️ {escape(_t(lang, 'warning'))}")
    buy_penalty = float(result.config.buy_price_penalty) * 100
    sell_penalty = float(result.config.sell_price_penalty) * 100
    max_sell_penalty = max(float(result.config.sell_price_penalty_10s), float(result.config.sell_price_penalty_30s), float(result.config.sell_price_penalty_60s)) * 100
    lines.extend([f'''<a href="{referral}">⚡️ {escape(_t(lang, 'copy_with'))}</a>''', '<i>' + escape(_t(lang, 'footer').format(count=f'{result.processed_trade_count:,}', buy=f'{buy_penalty:g}', sell=f'{sell_penalty:g}–{max_sell_penalty:g}')) + '</i>'])
    return '\n'.join(lines)

def render_telegram_report(result: BacktestResult | None=None, *, wallet_address: str='', lang: str='zh-CN', profile: Mapping[str, Any] | None=None, metrics: Mapping[str, Any] | None=None, referral_url: str | None=None, max_length: int=TELEGRAM_TEXT_LIMIT) -> str:
    """Render Telegram HTML from a backtest or stored metrics without recalculating."""
    context: BacktestResult | _StoredReportContext
    if result is None:
        if metrics is None:
            raise ValueError('A backtest result or complete stored metrics is required')
        config_keys = {field.name for field in fields(BacktestConfig)}
        context = _StoredReportContext(config=BacktestConfig.create(**{key: value for key, value in metrics['config'].items() if key in config_keys}), data_quality=metrics['data_quality'], processed_trade_count=int(metrics['processed_trade_count']))
        if profile is None:
            profile = (metrics.get('gmgn_stats_30d') or {}).get('common') or {}
    else:
        context = result
    profile = profile or {}
    if metrics is None:
        assert result is not None
        metrics = build_legacy_metrics(result, wallet_address=wallet_address, profile=profile)
    resolved_referral_url = referral_url or build_copy_trade_url(wallet_address)
    layouts = ((20, 14), (20, 10), (20, 7), (20, 5), (20, 3), (20, 0), (15, 0), (10, 0), (5, 0), (0, 0))
    for recent_limit, daily_limit in layouts:
        report = _build_report(context, metrics, wallet_address=wallet_address, lang=lang, profile=profile, referral_url=resolved_referral_url, recent_limit=recent_limit, daily_limit=daily_limit)
        if len(report) <= max_length:
            return report
    raise ValueError('Telegram report summary exceeds the configured text limit')
# ===== END copybot/telegram_report.py =====

# ===== BEGIN run_robinhood.py =====
import argparse
import json
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Any

def analyze_wallet(wallet_address: str, lang: str='zh-CN', ref_code: str='', bot_name: str='', client: str='tg', include_all_tokens: bool=False, skip_db: bool=True, *, max_trades: int=5000, buy_price_penalty: str='0.025', sell_price_penalty: str='0.025', include_target_fees: bool=False, cache_dir: str | None='.cache/gmgn', gmgn_client: GMGNClient | None=None) -> dict[str, Any]:
    """Fetch one wallet, run the spot copy backtest, and build its TG report.

    ``ref_code``, ``bot_name`` and ``skip_db`` are accepted for call-site
    compatibility with the Polymarket script. No database write is performed.
    """
    del ref_code, bot_name, skip_db
    analysis_started = time.perf_counter()
    api = gmgn_client or GMGNClient()
    cache_path = Path(cache_dir) / f'robinhood-{wallet_address.lower()}-{max_trades}.json' if cache_dir else None
    gmgn_stats: dict[str, Any] = {}
    gmgn_stats_error = ''
    with ThreadPoolExecutor(max_workers=2, thread_name_prefix='gmgn-wallet') as executor:
        activity_future = executor.submit(api.fetch_wallet_activities, wallet_address, limit=max_trades, cache_path=cache_path)
        stats_future = executor.submit(api.fetch_wallet_stats, wallet_address, period='30d')
        payload = activity_future.result()
        trades, quality = normalize_gmgn_payload(payload)
        config = BacktestConfig.create(max_trades=max_trades, buy_price_penalty=buy_price_penalty, sell_price_penalty=sell_price_penalty, include_observed_target_fees=include_target_fees)
        result = run_backtest(trades, config, normalization_quality=quality)
        try:
            gmgn_stats = stats_future.result()
        except Exception as exc:
            gmgn_stats_error = str(exc)
    profile = gmgn_stats.get('common') if isinstance(gmgn_stats.get('common'), dict) else {}
    legacy_metrics = build_legacy_metrics(result, wallet_address=wallet_address, profile=profile, include_all_tokens=include_all_tokens)
    report_text = render_telegram_report(result, wallet_address=wallet_address, lang=lang, profile=profile, metrics=legacy_metrics)
    metrics = result.to_dict(include_trade_results=client == 'web' and include_all_tokens)
    metrics.update(legacy_metrics)
    if gmgn_stats:
        metrics['gmgn_stats_30d'] = gmgn_stats
    if gmgn_stats_error:
        metrics['gmgn_stats_error'] = gmgn_stats_error
    metrics['analysis_elapsed_seconds'] = round(time.perf_counter() - analysis_started, 3)
    return {'report_text': report_text, 'metrics': metrics}

def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description='Analyze a Robinhood Chain wallet for copy trading')
    parser.add_argument('wallet')
    parser.add_argument('lang', nargs='?', choices=SUPPORTED_LANGUAGES, default='zh-CN')
    parser.add_argument('--max-trades', type=int, default=5000)
    parser.add_argument('--json', action='store_true', help='print report and metrics as JSON')
    parser.add_argument('--include-target-fees', action='store_true')
    parser.add_argument('--no-cache', action='store_true', help='disable the activity checkpoint cache')
    return parser

def main(argv: list[str] | None=None) -> int:
    args = _parser().parse_args(argv)
    output = analyze_wallet(args.wallet, lang=args.lang, max_trades=args.max_trades, include_target_fees=args.include_target_fees, cache_dir=None if args.no_cache else '.cache/gmgn', include_all_tokens=args.json, client='web' if args.json else 'tg')
    if args.json:
        print(json.dumps(output, ensure_ascii=False, indent=2))
    else:
        print(output['report_text'])
    return 0
if __name__ == '__main__':
    raise SystemExit(main())
# ===== END run_robinhood.py =====
